head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > P > focusOnOuterDiv]<br/>웹접근성 향상을 위해 컴포넌트의 최외곽 div 요소에 Tab 키로 포커스가 이동할 수 있도록 설정합니다.",
    "validation" : [
        "미설정(기본값 false) 시 최외곽 div 요소에 tabindex 가 설정되지 않아 Tab 키로 Calendar 컴포넌트 자체를 포커스할 수 없습니다.",
        "true 설정 시 최외곽 div 요소에 tabindex='0' 이 설정되어 Tab 키 이동 순서에 포함됩니다.",
        "false 설정 시 최외곽 div 요소에 tabindex 가 설정되지 않아 포커스는 Calendar 내부의 개별 인터랙티브 요소(날짜 셀, 버튼 등)로 이동합니다.",
        "accessibility=true 이면 focusOnOuterDiv 속성이 true 로 강제 설정됩니다.",
        "tabIndex 속성을 설정하면 focusOnOuterDiv 속성은 무시되고 tabIndex 값이 우선 적용됩니다.",
        "실제로 컴포넌트 자체에 Tab 키로 포커스를 이동하려면 accessibility 속성을 true 로 설정해야 합니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        focusOnOuterDiv : con_focusOnOuterDiv.getText(),
        accessibility : con_accessibility.getText(),
        tabIndex : con_tabIndex.getValue()
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onfocus"]);

    await $c.gcm.createBasicCalendar(cList, eList);
}



// accessibility=true + focusOnOuterDiv=true 조합에서 최외곽 div 포커스 시 onfocus 이벤트 발생 확인
scwin.target1_onfocus = function (e) {
    // validation: 실제로 컴포넌트 자체에 Tab 키로 포커스를 이동하려면 accessibility=true 도 함께 설정 필요
    wf_body_bottom.getObj("scwin").setReturnValue("[onfocus 이벤트 발생] 최외곽 div 포커스됨 (accessibility=" + target1.options.accessibility + ", focusOnOuterDiv=" + target1.options.focusOnOuterDiv + ")");
};



// [공통] 최외곽 div 의 tabindex 속성 확인 + Tab 키 포커스 가능 여부
scwin.getOuterDivTabIndex = function () {
    let calendarRender = target1.render;
    let outerTag = calendarRender.tagName.toLowerCase();
    let outerTabIdx = calendarRender.getAttribute('tabindex');
    let acc = target1.options.accessibility;

    // validation: true 설정 시 최외곽 div 요소에 tabindex='0' 이 설정되어 Tab 키 이동 순서에 포함됨
    // validation: 미설정(기본값 false)/false 설정 시 최외곽 div 요소에 tabindex 가 설정되지 않아 Tab 키로 Calendar 컴포넌트 자체를 포커스할 수 없음
    let outerHasTabIdx = (outerTabIdx !== null);
    wf_body_bottom.getObj("scwin").setReturnValue("[최외곽 div tabindex 속성] outerTag='" + outerTag + "', tabindex=" + (outerHasTabIdx ? "'" + outerTabIdx + "'" : "미설정"));

    // validation: 실제로 컴포넌트 자체에 Tab 키로 포커스를 이동하려면 accessibility 속성을 true 로 설정해야 함
    // (accessibility=true 일 때만 외부 div 포커스 흐름이 실효성 있음)
    let canFocusComp = (outerHasTabIdx && acc === true);
    wf_body_bottom.getObj("scwin").setReturnValue("[Tab 키로 컴포넌트 자체 포커스 실효성] " + (canFocusComp ? "가능 (accessibility=true + tabindex 설정)" : "불가 (accessibility=" + acc + ", tabindex=" + (outerHasTabIdx ? "'" + outerTabIdx + "'" : "미설정") + ")"));
}



scwin.btn_getInfo_onclick = function (e) {
    scwin.getOuterDivTabIndex();
}
